INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66721670', 66721670, 'analyze_legacy', 'Provinsi Kalimantan Utara', 'provinsi', 'Dinas Pekerjaan Umum, Penataan Ruang, Perumahan dan Kawasan Permukiman', 'Normalisasi Sungai Apung Jl. Kenanga RT.12 Desa Apung Kab. Bulungan', 'Pekerjaan Konstruksi', 'Pengadaan Langsung', 'Kalimantan Utara, Bulungan (Kab.)', 200000000, 'May 2026', 'APBD', 1, 1, '1 Paket', '1. Memperbaiki dan mengembalikan fungsi normal dari sungai Apung 2. Merapikan bentuk alur sungai, memperlebar kembali badan sungai dan menggali sedimentasi agar sungai menjadi lebih dalam, sehingga aliran air sungai semakin lancar, kapasitas daya tampung sungai serta debit arus sungai ideal serta berfungsi juga sebagai pengendali banjir', 'Dalam pelaksanaan pekerjaan yang dimaksud, penyedia jasa: 1. Diwajibkan untuk melakukan pengukuran lapangan dan membuat Shop Drawing sebelum memulai pelaksanaan pekerjaan dan diakhir pelaksanaan pekerjaan membuat As Built Drawing untuk diajukan dan disetujui oleh Pejabat Pembuat Komitmen; 2. Diwajibkan melaksanakan dan menyelesaikan pekerjaan sesuai dengan jadwal pelaksanaan pekerjaan yang telah ditetapkan sesuai spesifikasi teknis dalam kontrak; 3. Diwajibkan melaporkan pelaksanaan pekerjaan secara periodik kepada Pejabat Pembuat Komitmen; 4. Diwajibkan untuk mengikuti rapat-rapat yang ditentukan oleh Pejabat Pembuat Komitmen, seperti Pra Construction Meeting, Rapat Bulanan, Cause Meeting, dan rapat lainnya sebagai kendali pelaksanaan pekerjaan dan melaksanakan hasil rapat tersebut; 5. Memberikan peringatan dini dan keterangan yang diperlukan untuk pemeriksaan pelaksanaan yang dilakukan Pejabat Pembuat Komitmen; 6. Diwajibkan menyerahkan hasil pekerjaan sesuai dengan jadwal penyerahan pekerjaan yang telah ditetapkan dalam kontrak; 7. Mengambil langkah-langkah yang memadai untuk melindungi lingkungan baik di dalam maupun di luar tempat kerja dan membatasi perusakan dan pengaruh/gangguan kepada masyarakat maupun miliknya, sebagai akibat polusi, kebisingan dan kerusakan lain yang disebabkan kegiatan penyedia jasa; 8. Seluruh kegiatan dalam pelaksanaan pekerjaan di lapangan harus didokumentasikan dengan foto-foto asli yang dilampirkan dalam laporan hasil pekerjaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2961363);
