INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66721526', 66721526, 'analyze_legacy', 'Lembaga Penyiaran Radio Republik Indonesia', 'central', 'RRI YOGYAKARTA', 'Kendaraan Bermotor Roda 4 Eselon II', 'Jasa Lainnya', 'Dikecualikan', 'DI Yogyakarta, Yogyakarta (Kota)', 90000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 3, Unit, @ 30000000 )', '1. Kendaraan Bermotor Roda 4 Eselon II ( 3, Unit, @ 30000000 );', 'Pemeliharaan ringan kendaraan bermotor roda-4 Eselon II dimaksudkan untuk menjaga kondisi, kenyamanan, dan kelaikan operasional kendaraan dinas pimpinan agar selalu siap digunakan dalam mendukung pelaksanaan tugas kedinasan. Pemeliharaan dilakukan secara berkala tanpa pembongkaran besar, dengan memperhatikan standar perawatan kendaraan dinas pimpinan. Ruang lingkup pekerjaan meliputi servis ringan kendaraan, antara lain penggantian oli mesin, pengecekan dan pembersihan filter udara, pemeriksaan sistem rem dan sistem pendingin mesin, pengecekan aki, kondisi ban, sistem kelistrikan, serta kelengkapan kendaraan lainnya. Selain itu, belanja ini mencakup pembelian Bahan Bakar Minyak (BBM) sesuai jenis kendaraan untuk mendukung mobilitas dan kegiatan operasional kendaraan dinas Eselon II, dengan penggunaan yang tertib, efisien, dan dapat dipertanggungjawabkan sesuai ketentuan peraturan perundang-undangan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2962019);
