INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66722334', 66722334, 'analyze_legacy', 'Badan Riset dan Inovasi Nasional', 'central', 'Deputi Bidang Infrastruktur Riset dan Inovasi', 'Pemeliharaan Panel Elektrikal pada KST Serpong (Bacharuddin Jusuf Habibie)', 'Jasa Lainnya', 'E-Purchasing', 'Banten, Tangerang Selatan (Kota)', 1200000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '15 paket', 'Pemeliharaan Trafo : 1. Pemeriksaan Visual - Pemeriksaan kondisi fisik trafo (tangki, bushing, radiator, konservator). - Pemeriksaan adanya kebocoran oli trafo. - Pemeriksaan kondisi grounding trafo. - Pemeriksaan indikator level oli, temperatur, dan silica gel. 2 Pembersihan : - Pembersihan permukaan trafo dari debu dan kotoran. - Pembersihan bushing dan terminal. 3 Pengujian dan Pengukuran : - Pengukuran tahanan isolasi (Insulation Resistance Test). - Pengujian rasio transformator (TTR – Transformer Turn Ratio). - Pengujian tahanan pembumian (grounding resistance). - Pengujian minyak trafo (BDV test, kadar air, dan DGA jika diperlukan). - Pengukuran suhu operasi trafo. 4 Pemeliharaan Sistem Pendingin : - Pemeriksaan kipas (fan) dan pompa oli. - Pemeriksaan fungsi relay temperatur (WTI/OTI). - Pemeriksaan sistem sirkulasi oli. 5 Perbaikan Minor : - Pengencangan baut dan koneksi. - Penggantian silica gel. - Penambahan atau penggantian oli trafo (jika diperlukan). || Lingkup Pekerjaan Pemeliharaan Panel Kubikel : 1 Pemeriksaan Visual - Pemeriksaan kondisi fisik panel dan enclosure. - Pemeriksaan indikator tegangan, arus, dan posisi switchgear. - Pemeriksaan kondisi mekanisme operasi (handle, interlock). 2 Pembersihan - Pembersihan ruang panel dari debu dan kotoran. - Pembersihan isolator dan komponen internal. 3 Pengujian dan Pengukuran : - Pengukuran tahanan isolasi panel. - Pengujian fungsi relay proteksi. - Pengujian sistem interlock. - Pengujian breaker (VCB/LBS) termasuk open-close test. - Pengukuran tahanan kontak (contact resistance test). 4 Pemeliharaan Komponen - Pelumasan mekanisme breaker. - Pemeriksaan dan pengencangan terminal kabel. - Pemeriksaan CT dan PT. - Pemeriksaan sistem proteksi dan kontrol. 5 Pengujian Sistem Proteksi - Setting dan kalibrasi relay proteksi. - Uji trip dan koordinasi proteksi.', 'Pemeliharaan Trafo : 1. Pemeriksaan Visual - Pemeriksaan kondisi fisik trafo (tangki, bushing, radiator, konservator). - Pemeriksaan adanya kebocoran oli trafo. - Pemeriksaan kondisi grounding trafo. - Pemeriksaan indikator level oli, temperatur, dan silica gel. 2 Pembersihan : - Pembersihan permukaan trafo dari debu dan kotoran. - Pembersihan bushing dan terminal. 3 Pengujian dan Pengukuran : - Pengukuran tahanan isolasi (Insulation Resistance Test). - Pengujian rasio transformator (TTR – Transformer Turn Ratio). - Pengujian tahanan pembumian (grounding resistance). - Pengujian minyak trafo (BDV test, kadar air, dan DGA jika diperlukan). - Pengukuran suhu operasi trafo. 4 Pemeliharaan Sistem Pendingin : - Pemeriksaan kipas (fan) dan pompa oli. - Pemeriksaan fungsi relay temperatur (WTI/OTI). - Pemeriksaan sistem sirkulasi oli. 5 Perbaikan Minor : - Pengencangan baut dan koneksi. - Penggantian silica gel. - Penambahan atau penggantian oli trafo (jika diperlukan). || Lingkup Pekerjaan Pemeliharaan Panel Kubikel : 1 Pemeriksaan Visual - Pemeriksaan kondisi fisik panel dan enclosure. - Pemeriksaan indikator tegangan, arus, dan posisi switchgear. - Pemeriksaan kondisi mekanisme operasi (handle, interlock). 2 Pembersihan - Pembersihan ruang panel dari debu dan kotoran. - Pembersihan isolator dan komponen internal. 3 Pengujian dan Pengukuran : - Pengukuran tahanan isolasi panel. - Pengujian fungsi relay proteksi. - Pengujian sistem interlock. - Pengujian breaker (VCB/LBS) termasuk open-close test. - Pengukuran tahanan kontak (contact resistance test). 4 Pemeliharaan Komponen - Pelumasan mekanisme breaker. - Pemeriksaan dan pengencangan terminal kabel. - Pemeriksaan CT dan PT. - Pemeriksaan sistem proteksi dan kontrol. 5 Pengujian Sistem Proteksi - Setting dan kalibrasi relay proteksi. - Uji trip dan koordinasi proteksi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2962412);
