INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66723822', 66723822, 'analyze_legacy', 'Badan Riset dan Inovasi Nasional', 'central', 'Deputi Bidang Infrastruktur Riset dan Inovasi', 'Kalibrasi Alat Riset pada Laboratorium BRIN', 'Jasa Lainnya', 'Pengadaan Langsung', 'LAINNYA, Lainnya', 1500000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '66 Paket', 'Persiapan Kalibrasi Identifikasi dan inventarisasi alat yang akan dikalibrasi. Pemeriksaan awal kondisi fisik alat. Verifikasi kelengkapan aksesori, sensor, dan probe. Penentuan metode dan standar kalibrasi yang digunakan (mengacu pada standar nasional/internasional seperti ISO/IEC 17025). Penyusunan jadwal pelaksanaan kalibrasi. 2. Pelaksanaan Kalibrasi Kalibrasi dilakukan oleh laboratorium terakreditasi. Pengujian dan pengukuran parameter sesuai spesifikasi alat, meliputi: Akurasi Presisi Repeatability Linearitas (jika relevan) Penggunaan standar acuan (traceable ke standar nasional/internasional). Penyesuaian (adjustment) apabila ditemukan penyimpangan di luar toleransi. Dokumentasi hasil pengukuran selama proses kalibrasi. 3. Verifikasi dan Validasi Evaluasi hasil kalibrasi terhadap batas toleransi yang ditetapkan. Penentuan status alat: Layak digunakan Layak dengan catatan Tidak layak digunakan Uji fungsi (functional test) pasca kalibrasi. 4. Dokumentasi dan Sertifikasi Penerbitan sertifikat kalibrasi resmi. Sertifikat harus memuat: Identitas alat (merk, tipe, serial number) Metode kalibrasi Hasil pengukuran dan ketidakpastian (uncertainty) Traceability standar Tanggal kalibrasi dan masa berlaku Pemberian label/stiker kalibrasi pada alat. 5. Pelaporan Penyusunan laporan hasil kalibrasi secara lengkap. Rekapitulasi seluruh alat yang dikalibrasi. Rekomendasi tindak lanjut (repair, adjustment, atau penggantian alat). 6. Tindak Lanjut (Opsional) Perbaikan ringan (minor adjustment). Rekomendasi perbaikan besar atau penggantian komponen. Penyusunan jadwal kalibrasi berikutnya (periodik).', 'Persiapan Kalibrasi Identifikasi dan inventarisasi alat yang akan dikalibrasi. Pemeriksaan awal kondisi fisik alat. Verifikasi kelengkapan aksesori, sensor, dan probe. Penentuan metode dan standar kalibrasi yang digunakan (mengacu pada standar nasional/internasional seperti ISO/IEC 17025). Penyusunan jadwal pelaksanaan kalibrasi. 2. Pelaksanaan Kalibrasi Kalibrasi dilakukan oleh laboratorium terakreditasi. Pengujian dan pengukuran parameter sesuai spesifikasi alat, meliputi: Akurasi Presisi Repeatability Linearitas (jika relevan) Penggunaan standar acuan (traceable ke standar nasional/internasional). Penyesuaian (adjustment) apabila ditemukan penyimpangan di luar toleransi. Dokumentasi hasil pengukuran selama proses kalibrasi. 3. Verifikasi dan Validasi Evaluasi hasil kalibrasi terhadap batas toleransi yang ditetapkan. Penentuan status alat: Layak digunakan Layak dengan catatan Tidak layak digunakan Uji fungsi (functional test) pasca kalibrasi. 4. Dokumentasi dan Sertifikasi Penerbitan sertifikat kalibrasi resmi. Sertifikat harus memuat: Identitas alat (merk, tipe, serial number) Metode kalibrasi Hasil pengukuran dan ketidakpastian (uncertainty) Traceability standar Tanggal kalibrasi dan masa berlaku Pemberian label/stiker kalibrasi pada alat. 5. Pelaporan Penyusunan laporan hasil kalibrasi secara lengkap. Rekapitulasi seluruh alat yang dikalibrasi. Rekomendasi tindak lanjut (repair, adjustment, atau penggantian alat). 6. Tindak Lanjut (Opsional) Perbaikan ringan (minor adjustment). Rekomendasi perbaikan besar atau penggantian komponen. Penyusunan jadwal kalibrasi berikutnya (periodik).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 0, 2963933);
