INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66730857', 66730857, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB BANGKA BARAT', 'Biaya Jasa Manajemen Building periode April sampai Desember 2026 BPS Kabupaten Bangka Barat', 'Jasa Lainnya', 'E-Purchasing', 'Kep. Bangka Belitung, Bangka Barat (Kab.)', 261590735, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Tahun @ Rp261.510.000,-', 'Pengadaan Tenaga Alih Daya Jasa Keamanan dan Jasa Kebersihan periode April sampai Desember BPS Kabupaten Bangka Barat Tahun 2026', 'Pengadaan Tenaga Alih Daya Jasa Keamanan dan Jasa Kebersihan periode April sampai Desember BPS Kabupaten Bangka Barat Tahun 2026 Tenaga Jasa Keamanan 3 personel - Memiliki KTA yang masih berlaku; - Memiliki Surat Keterangan Berkelakuan Bark; - Berbadan tegap proporsional terhadap BB; - Tinggi badan minimal 165 cm - Berbadan sehat yang dibuktikan dengan surat keterangan dokter dan tidak mempunyai riwayat penyakit yang akan mengganggu pelaksanaan tugas - Diutamakan sudah berpengalaman sebagai petugas keamanan/security - Tidak memiliki tattoo/ bekas tattoo dan tidak bertindik - Bersikap sopan, jujur dan dapat bekerja sama dalam tim - Mampu berkomunikasi dan mempunyai semangat tinggi - Siap bekerja shift dan menaati segala aturan yang akan ditetapkan oleh BPS Kabupaten Bangka Barat - Berkelakuan baik. - Usia 25 - 45 Tahun - Pendidikan minimal SMA/Sederajat - Tidak memiliki Tatoo/bekas Tatoo pada bagian tubuh yang terlihat dan tidak bertindik; - Ulet dan pekerja keras. - Memiliki keahlian tambahan sebagai gardener - Menaati segala aturan yang akan ditetapkan oleh BPS Kabupaten Bangka Barat - Bersama Tim Subbagian Umum melaksanakan koordinasi dengan keamanan lingkungan Tenaga jasa kebersihan 2 personel - Pendidikan minimal SMA/Sederajat - Memiliki Surat Keterangan Berkelakuan Baik; - Sehat jasmani dan rohani - Berpenampilan menarik - Komunikatif - Usia 25 - 45 Tahun - Mampu bekerja sama secara individu dan tim - Tidak memiliki Tatoo/bekas Tatoo pada bagian tubuh yang terlihat dan tidak bertindik; - Ulet dan pekerja keras. - Memiliki keahlian tambahan sebagai gardener - Menaati segala aturan yang akan ditetapkan oleh BPS Kabupaten Bangka Barat', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2966082);
